al para lidar com interrupções`n    agent_lock = threading.Lock()`n    is_processing = False`n`n    # Chat history para o painel`n    chat_log = []`n    _chat_log_lock = threading.Lock()`n`n    def _add_chat(role: str, name: str, text: str):`n        `"`"`"Adiciona uma entrada ao log de chat.`"`"`"`n        import datetime`n        with _chat_log_lock:`n            chat_log.append({`n                `"role`": role,          # `"user`" | `"assistant`" | `"system`"`n                `"name`": name,`n                `"text`": text,`n                `"time`": datetime.datetime.now().strftime(`"%H:%M:%S`")`n            })`n            # Mantém apenas as últimas 200 mensagens`n            if len(chat_log) > 200:`n                del chat_log[:len(chat_log) - 200]`n`n    # Captura de logs do sistema`n    system_logs = []`n    _log_lock = threading.Lock()`n`n    class _LogCapture:`n        `"`"`"Intercepta print() para capturar logs do sistema.`"`"`"`n        def __init__(self, original):`n            self._original = original`n        def write(self, text):`n            self._original.write(text)`n            if text.strip():`$2"

